KIT = '<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700;800&family=IBM+Plex+Mono:wght@400;500;600&display=swap">\n<style>\n/* Otl Aicher, Munich 1972. Strict grid, one thing per cell, mono labels, thin rules.\n   The palette is defined by what it excludes: no red, no true black. Committed to a\n   light ground on purpose, because this is projected in a lit room. */\n:root{\n  --paper:#FAFAF8; --ink:#16181A; --ink2:#4A5054; --rule:#C9CCC9; --fill:#EFF0EE;\n  --blue:#2E7FC2; --green:#5EA654; --violet:#7E5AA2; --orange:#E08A2E; --silver:#B9BDBA;\n}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;background:var(--paper);color:var(--ink);\n font-family:Archivo,"Helvetica Neue",Helvetica,Arial,sans-serif;font-size:20px;line-height:1.5}\n.wrap{max-width:1360px;margin:0 auto;padding:40px 38px 96px}\n.lbl{font-family:"IBM Plex Mono",ui-monospace,Menlo,monospace;font-size:12px;letter-spacing:.22em;\n text-transform:uppercase;color:var(--ink2)}\n.mast{display:flex;justify-content:space-between;align-items:flex-end;gap:26px;\n border-bottom:4px solid var(--ink);padding-bottom:15px;flex-wrap:wrap}\n.mast h1{margin:6px 0 0;font-size:58px;line-height:.98;font-weight:700;letter-spacing:-.035em;\n text-wrap:balance}\n.mast .rt{text-align:right}\n.sub{display:flex;flex-wrap:wrap;border-bottom:1px solid var(--rule);margin-bottom:34px}\n.sub div{padding:12px 26px 12px 0;margin-right:26px;border-right:1px solid var(--rule)}\n.sub div:last-child{border-right:0;margin-right:0}\n.sub b{display:block;font-size:25px;font-weight:700;letter-spacing:-.02em;line-height:1.15}\n.nav{display:flex;gap:10px;margin:26px 0 0;flex-wrap:wrap}\n.nav a{display:inline-block;padding:10px 20px;border:2px solid var(--ink);text-decoration:none;\n color:var(--ink);font-family:"IBM Plex Mono",monospace;font-size:12px;letter-spacing:.18em;\n text-transform:uppercase;background:var(--paper)}\n.nav a.here{background:var(--ink);color:var(--paper)}\n.nav a:hover,.nav a:focus-visible{background:var(--blue);border-color:var(--blue);color:#fff}\n:focus-visible{outline:3px solid var(--orange);outline-offset:3px}\na{color:var(--blue)}\n.note{background:var(--fill);border-left:6px solid var(--orange);padding:17px 22px;margin:32px 0 0}\n.note p{margin:0 0 9px;font-size:18px}.note p:last-child{margin:0}\n.foot{margin-top:52px;border-top:1px solid var(--rule);padding-top:17px;font-size:16px;color:var(--ink2)}\n.foot p{margin:0 0 7px}\n@media print{.nav{display:none}body{font-size:12pt}.wrap{padding:0}}\n</style>'
